window.S17Page={"sceneId":"c4","caseId":"s17x-c4-casing-standoff","name":"套管居中度智能评估","title":"套管居中度智能评估","summary":"改变偏心、侧向载荷与扶正器跨距，观察截面间隙及支撑之间的下垂，比较有载与无载评估。","directory":"expansion-cases","caseVersion":"1.2.0","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){'use strict';
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));const sum=a=>a.reduce((s,x)=>s+x,0),mean=a=>a.length?sum(a)/a.length:0;
function rng(seed){let s=seed>>>0;return ()=>{s=(1664525*s+1013904223)>>>0;return s/4294967296}}
function solve(A,b){A=A.map((r,i)=>r.slice().concat(b[i]));const n=b.length;for(let j=0;j<n;j++){let p=j;for(let i=j+1;i<n;i++)if(Math.abs(A[i][j])>Math.abs(A[p][j]))p=i;[A[j],A[p]]=[A[p],A[j]];if(Math.abs(A[j][j])<1e-12)throw Error('训练矩阵退化');let v=A[j][j];for(let k=j;k<=n;k++)A[j][k]/=v;for(let i=0;i<n;i++)if(i!==j){v=A[i][j];for(let k=j;k<=n;k++)A[i][k]-=v*A[j][k]}}return A.map(r=>r[n])}
function ridge(rows,features,outputs){const raw=rows.map(d=>features(d.x)),d=raw[0].length,mu=Array.from({length:d},(_,j)=>mean(raw.map(r=>r[j]))),sd=mu.map((m,j)=>Math.max(1e-8,Math.sqrt(mean(raw.map(r=>(r[j]-m)**2)))));const scale=x=>[1,...features(x).map((v,j)=>(v-mu[j])/sd[j])],X=rows.map(r=>scale(r.x)),A=Array.from({length:d+1},(_,j)=>Array.from({length:d+1},(_,k)=>sum(X.map(r=>r[j]*r[k]))+(j===k&&j>0?.01:0)));const coef=Array.from({length:outputs},(_,o)=>solve(A,Array.from({length:d+1},(_,j)=>sum(rows.map((r,i)=>X[i][j]*r.y[o])))));return {predict:x=>{const z=scale(x);return coef.map(c=>sum(c.map((v,j)=>v*z[j])))},coef,mu,sd}}
function batch(n,seed,make){const r=rng(seed);return Array.from({length:n},(_,i)=>make(r,i))}function mae(pred,truth){return mean(pred.map((p,i)=>Math.abs(p-truth[i])))}
const panel=(title,body)=>'<article class="panel"><h2>'+title+'</h2>'+body+'</article>';const plot=(title,body,desc='')=>'<article class="panel chart"><h2>'+title+'</h2>'+body+'<p class="small">'+desc+'</p></article>';

const features=x=>[x[0],x[1]*x[2]*x[2]*(.3+.7*Math.sin(x[3]*Math.PI/180))];function response(x){return 30-x[0]-.025*x[1]*x[2]*x[2]*(.3+.7*Math.sin(x[3]*Math.PI/180))}function make(r){let x=[20*r(),.5+1.5*r(),6+12*r(),15+70*r()];return {x,y:[response(x)+(r()-.5)*.6]}}const train=batch(240,17401,make),test=batch(80,27401,make),model=ridge(train,features,1);
function run(p={}){p=Object.assign({"ecc": 12, "load": 1.3, "spacing": 12},p);const x=[p.ecc,p.load,p.spacing,60],gap=model.predict(x)[0],baseline=30-p.ecc,sag=baseline-gap;const points=Array.from({length:121},(_,i)=>{const depth=i*.5;return {depth,gap:baseline-sag*Math.sin(Math.PI*(depth%p.spacing)/p.spacing)**2}});const candidates=[6,9,12,15,18].map(s=>({spacing:s,gap:model.predict([p.ecc,p.load,s,60])[0],supports:Math.floor(60/s)+1}));return {params:p,points,gap,baseline,sag,candidates,metrics:{mae:mae(test.map(d=>model.predict(d.x)[0]),test.map(d=>d.y[0])),denominator:80,standoff:gap/30*100},summary:'当前最小间隙 '+gap.toFixed(2)+' mm，'+(gap<0?'诊断间隙比 ':'居中度 ')+(gap/30*100).toFixed(1)+'%；无载几何估计 '+baseline.toFixed(2)+' mm。'+(gap<0?' 预测越过接触边界，需含接触力模型复核。':''),data:{kind:'固定种子教学变形样本',train:240,test:80,geometry:{boreRadiusMM:120,casingRadiusMM:90},inclinationDeg:60}}}
function describe(d){return '井段位置 '+d.depth.toFixed(1)+' m，当前间隙 '+d.gap.toFixed(2)+' mm'}
function render(r,h){const {n,svg,axes,path,metric,table}=h;const ymin=Math.min(-10,Math.floor(r.gap/10)*10),ymax=40,sy=v=>258-(v-ymin)/(ymax-ymin)*236;let curve=axes('井段位置 / m','窄侧间隙 / mm',[0,60],[ymin,ymax]);curve+=path(r.points.map(d=>[58+d.depth/60*497,sy(d.gap)]),'#267d78');curve+=path([[58,sy(r.baseline)],[555,sy(r.baseline)]],'#c18b44',true);for(let z=0;z<=60;z+=r.params.spacing)curve+='<path d="M'+(58+z/60*497)+' 238v20" stroke="#6a8586" stroke-width="3"/>';const physicalGap=Math.max(0,Math.min(30,r.gap)),shift=(30-physicalGap)*(100/120);let cross='<circle cx="240" cy="145" r="110" fill="#dac7aa"/><circle cx="240" cy="145" r="100" fill="#f6faf7"/><circle cx="'+(240+shift)+'" cy="145" r="75" fill="#718f9a"/><circle cx="'+(240+shift)+'" cy="145" r="62" fill="#f6faf7"/><path d="M'+(315+shift)+' 145H340" stroke="#bb5d4a" stroke-width="3"/><text x="370" y="110" style="font-size:15px">预测间隙 '+n(r.gap)+' mm</text><text x="370" y="145" style="font-size:15px">'+(r.gap<0?'接触：自由变形假设失效':'居中度 '+n(r.metrics.standoff,1)+'%')+'</text><text x="100" y="265" style="font-size:15px">井眼半径 120 mm · 套管外半径 90 mm</text><text x="100" y="291" style="font-size:14px">同一比例：120 mm = 100 图像单位</text>' ;return '<div class="metric-grid">'+metric('预测最小间隙',n(r.gap),'mm')+metric('无载几何基线',n(r.baseline),'mm')+metric(r.gap<0?'预测间隙比（接触诊断）':'居中度',n(r.metrics.standoff,1),'%')+metric('留出间隙 MAE',n(r.metrics.mae),'mm · 80 组合')+'</div><div class="charts">'+plot('最差截面：窄侧还有多少间隙？',svg(cross),'井眼与套管半径和圆心偏移使用同一比例。负预测值保留作接触诊断；截面停在接触位置，不把实体穿透当作真实变形。')+plot('最差点在支撑之间',svg(curve),'绿色为受载间隙；金色虚线是无载基线；底部短线表示扶正支撑。形状用显式正弦平方展开，最小值来自回归预测。支撑从 0 m 起等跨距排列；若 60 m 非跨距整数倍，下一个支撑位于图外。')+'</div>'+panel('改变跨距：间隙与支撑数量一起看',table(['跨距 / m','预测最小间隙 / mm','间隙比 / %（负值仅诊断）','0–60 m 内支撑数（含端点）'],r.candidates.map(d=>[d.spacing,n(d.gap),n(d.gap/30*100,1),d.supports]))) }
g.CaseEngine={run,render,describe,response,model};})(globalThis);

